<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';import {useSessionStore} from '../stores/session';import {useRunStore} from '../stores/run';import type {Target} from '@shared/labops-targets.js';import {actorHeaders} from '../actor';import {responseError} from '../http';import AsyncState from './AsyncState.vue';import {useVisibleRefresh} from '../composables/useVisibleRefresh';
const props=defineProps<{section?:string}>(),emit=defineEmits<{navigate:[Target]}>(),session=useSessionStore(),run=useRunStore(),section=ref(props.section||'work'),busy=ref(false),error=ref(''),selected=ref<string|null>(null),title=ref('');
const list=computed(()=>section.value==='chat'?session.chatConversations:session.workConversations);watch(()=>props.section,v=>section.value=v||'work');onMounted(()=>session.loadConversations());useVisibleRefresh(()=>session.loadConversations(),()=>!run.inputLocked);
async function create(){if(busy.value)return;busy.value=true;error.value='';try{const res=await fetch('/api/conversations',{method:'POST',headers:{...actorHeaders(),'Content-Type':'application/json'},body:JSON.stringify({mode:section.value==='chat'?'chat':'task'})});if(!res.ok)throw await responseError(res);const c=await res.json();session.setCurrentMode(c.id,section.value==='chat'?'chat':'task');await session.loadConversations();emit('navigate',{view:'conversation',conversationId:c.id});}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function rename(){if(!selected.value)return;try{await session.renameConversation(selected.value,title.value);selected.value=null;}catch(e){error.value=(e as Error).message;}}
async function remove(){if(!selected.value||!confirm('删除此会话及其聊天显示，不撤销已提交的业务。继续？'))return;try{await session.removeConversation(selected.value);selected.value=null;}catch(e){error.value=(e as Error).message;}}
</script>
<template><div class="mobile-segments" role="tablist" aria-label="会话分区"><button role="tab" :aria-selected="section==='work'" @click="section='work';emit('navigate',{view:'assistant',section:'work'})">工作会话 {{session.workConversations.length}}</button><button role="tab" :aria-selected="section==='chat'" @click="section='chat';emit('navigate',{view:'assistant',section:'chat'})">聊天会话 {{session.chatConversations.length}}</button></div><p>{{section==='chat'?'只读查询 · DashScope / 当前已配置的规则引擎':'查询、准备方案、本人确认办理 · Agnes / 当前已配置的规则引擎'}}</p><button class="mobile-primary" :disabled="busy" @click="create">新建{{section==='chat'?'聊天':'工作'}}会话</button><p v-if="error" role="alert">{{error}}</p><AsyncState :loading="session.listLoading" :error="session.listError||''" :empty="!list.length" empty-text="此分区暂无会话。" @retry="session.loadConversations"><article v-for="c in list" :key="c.id" class="mobile-session-row"><button class="mobile-row" @click="emit('navigate',{view:'conversation',conversationId:c.id})"><b>{{c.title||'新会话'}}</b><span>{{c.preview||'尚未开始对话'}}</span><small>{{session.timeLabel(c.lastActivityAt)}} · {{c.messageCount}} 条消息</small></button><button aria-label="管理会话" @click="selected=c.id;title=c.title">更多</button></article></AsyncState><section v-if="selected" class="mobile-section"><h3>管理会话</h3><label>会话名称<input v-model="title" maxlength="120"></label><div class="mobile-actions"><button :disabled="busy" @click="rename">保存名称</button><button :disabled="busy||run.inputLocked" @click="remove">删除会话</button><button @click="selected=null">取消</button></div></section></template>
